}
async function g(source) {
  const f = setup(source);
  const r = await f.cpg.invoke('cpg.build', {path:'src/a.js'}, f.ctx);
  return { f, graph: JSON.parse(readFileSync(r.refs[0].path,'utf8')), r };
}
function cfg(graph) {
  return graph.edges.filter(e => e.type.startsWith('CFG_')).map(e => {
    const from = graph.nodes.find(n=>n.id===e.from);
    const to = graph.nodes.find(n=>n.id===e.to);
    const fl = from?.range?.start?.line ?? from?.type;
