{
  const g = await graphOf(`function readInput(){} function send(v){}
function run(a,b){
  let value;
  if (a) {
    value = readInput()
  } else if (b) {
    value = 1
  } else {
    value = 2
  }
  send(value)
}\n`);
  // RD to send's value
  const sendVal = g.nodes.filter(n=>n.type==='identifier'&&n.name==='value'&&n.role==='reference');
  for (const ref of sendVal) {
    const rds = g.edges.filter(e=>e.type==='REACHING_DEF'&&e.to===ref.id);
    console.log('ref L', ref.range.start.line, 'live', ref.cfgReachable, 'rds', rds.length);
    for (const e of rds) {
      const d = g.nodes.find(n=>n.id===e.from);
      console.log('  from', d.role, 'L'+d.range.start.line, 'live', d.cfgReachable);
    }
  }
}

