import { mkdtempSync, mkdirSync, writeFileSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { AtlasCpgSlice, AtlasCpgTaint } from './impl/src/index.mjs';

function setup(source) {
  const root = mkdtempSync(join(tmpdir(), 'adv3-'));
  const artifacts = mkdtempSync(join(tmpdir(), 'adv3a-'));
  mkdirSync(join(root, 'src'), { recursive: true });
  writeFileSync(join(root, 'src/a.js'), source);
  const cpg = new AtlasCpgSlice({ artifactRoot: join(artifacts, 'cpg'), maxSourceBytes: 64*1024, maxArtifactBytes: 512*1024, maxReachDefPairs: 4096 });
  const taint = new AtlasCpgTaint({ artifactRoot: join(artifacts, 'taint'), maxGraphBytes: 512*1024, maxResultBytes: 512*1024, maxDepth: 24, maxPaths: 32, maxSourceBytes: 64*1024, maxReachDefPairs: 4096 });
  return { root, cpg, taint, ctx: { root, budgetTokens: 50000 }, args: { path: 'src/a.js', sourceNames:['readInput'], sinkNames:['send'], depth:20 } };
}
async function g(source) {
  const f = setup(source);
  const r = await f.cpg.invoke('cpg.build', {path:'src/a.js'}, f.ctx);
  return {f, graph: JSON.parse(readFileSync(r.refs[0].path,'utf8'))};
}

// proper if/else both defs
{
  const {graph} = await g(`function readInput(){} function safe(){} function send(v){}
function run(flag){ let value; if(flag){ value=readInput() } else { value=safe() } send(value) }\n`);
  const ref = graph.nodes.find(n=>n.name==='value'&&n.role==='reference'&&n.range.start.line>=1);
  // find send's arg - last value ref
  const refs = graph.nodes.filter(n=>n.name==='value'&&n.role==='reference');
  const sendCall = graph.nodes.find(n=>n.calleeName==='send');
  const argRef = refs.find(n=>n.statement && graph.nodes.find(s=>s.id===n.statement && s.kind==='expression_statement'));
  for (const ref of refs) {
    const rds = graph.edges.filter(e=>e.type==='REACHING_DEF'&&e.to===ref.id);
    console.log('ref L'+ref.range.start.line, 'rds', rds.map(e=>'L'+graph.nodes.find(n=>n.id===e.from).range.start.line));
  }
}

// else-if false path: value from else should reach but doesn't; then always reaches
{
  const src = `function readInput(){} function send(v){}
function run(a,b){
  let value = 0;
  if (a) {
    value = readInput()
  } else if (b) {
    value = readInput()
  }
  send(value)
}\n`;
  const {graph,f} = await g(src);
  const refs = graph.nodes.filter(n=>n.name==='value'&&n.role==='reference');
  console.log('\nelse-if dual source');
  for (const ref of refs) {
    const rds = graph.edges.filter(e=>e.type==='REACHING_DEF'&&e.to===ref.id);
    console.log('ref L'+ref.range.start.line, 'live', ref.cfgReachable, 'rds', rds.map(e=>{
      const d=graph.nodes.find(n=>n.id===e.from); return `L${d.range.start.line}/live=${d.cfgReachable}`;
    }));
  }
  const t = await f.taint.invoke('cpg.taint', f.args, f.ctx);
  console.log('taint paths', t.payload.length);
  // both branches assign readInput - if only then re-anchors, still 1 path; if else also, still 1
}

// Critical: else-only taint source
{
  const src = `function readInput(){} function send(v){}
function run(a,b){
  let value = 0;
  if (a) {
    value = 1
  } else if (b) {
    value = readInput()
  }
  send(value)
}\n`;
  const {graph,f} = await g(src);
  const t = await f.taint.invoke('cpg.taint', f.args, f.ctx);
  console.log('\nelse-if ELSE source only: taint paths', t.payload.length, '(should be 1 if may-reach correct)');
  const refs = graph.nodes.filter(n=>n.name==='value'&&n.role==='reference');
  for (const ref of refs) {
    const rds = graph.edges.filter(e=>e.type==='REACHING_DEF'&&e.to===ref.id);
    console.log('ref L'+ref.range.start.line, 'rds', rds.map(e=>{
      const d=graph.nodes.find(n=>n.id===e.from); return `L${d.range.start.line}/live=${d.cfgReachable}`;
    }));
  }
  console.log(graph.nodes.filter(n=>n.type==='call'&&n.calleeName==='readInput').map(n=>`live=${n.cfgReachable}`));
}

// then-only with else-if: source always gens at if (false positive when a false)
{
  const src = `function readInput(){} function send(v){}
function run(a,b){
  let value = 0;
  if (a) {
    value = readInput()
  } else if (b) {
    value = 1
  }
  send(value)
}\n`;
  const {graph,f} = await g(src);
  const t = await f.taint.invoke('cpg.taint', f.args, f.ctx);
  console.log('\nelse-if THEN source: taint paths', t.payload.length);
  // RD: does initial 0 also reach?
  const refs = graph.nodes.filter(n=>n.name==='value'&&n.role==='reference');
  for (const ref of refs) {
    const rds = graph.edges.filter(e=>e.type==='REACHING_DEF'&&e.to===ref.id);
    console.log('ref L'+ref.range.start.line, 'rds', rds.map(e=>'L'+graph.nodes.find(n=>n.id===e.from).range.start.line));
  }
}

// switch case body - atomic reanchor?
{
  const src = `function readInput(){} function send(v){}
function run(x){
  let value = 0;
  switch (x) {
    case 1:
      value = readInput();
      break;
  }
  send(value)
}\n`;
  const {graph,f} = await g(src);
  const t = await f.taint.invoke('cpg.taint', f.args, f.ctx);
  console.log('\nswitch:', t.payload.length);
  console.log(graph.nodes.filter(n=>n.type==='statement').map(n=>`${n.kind} r=${n.cfgReachable}`).join(' | '));
}

// artifact schemaVersion and node fields
{
  const {graph} = await g(`function run(flag){ if(flag){ a() } else { b() } c() }\n`);
  console.log('\nschema', graph.schemaVersion);
  const stmt = graph.nodes.find(n=>n.type==='statement');
  const id = graph.nodes.find(n=>n.type==='identifier');
  console.log('stmt keys', Object.keys(stmt).sort().join(','));
  console.log('id keys', Object.keys(id).sort().join(','));
}

// break/continue as terminal? not in terminal()
{
  const {graph} = await g(`function run(){ while(x){ break; y() } z() }\n`);
  console.log('\nbreak terminal?', graph.edges.filter(e=>e.type.startsWith('CFG_')).map(e=>{
    const f=graph.nodes.find(n=>n.id===e.from); const t=graph.nodes.find(n=>n.id===e.to);
    return `${e.type} ${f?.kind||f?.type}->${t?.kind||t?.type}`;
  }).join(' | '));
}

// const fingerprint determinism for if
{
  const f1 = setup(`function run(flag){ if(flag){ a() } else { b() } }\n`);
  const f2 = setup(`function run(flag){ if(flag){ a() } else { b() } }\n`);
  const r1 = await f1.cpg.invoke('cpg.build',{path:'src/a.js'},f1.ctx);
  const r2 = await f2.cpg.invoke('cpg.build',{path:'src/a.js'},f2.ctx);
  console.log('\ndeterminism', r1.provenance.graphDigest===r2.provenance.graphDigest);
}

// if (false) else-if true structured inner still orphaned
{
  const src = `function readInput(){} function send(v){}
function run(){
  let value = 0;
  if (false) {
    value = 1
  } else if (true) {
    value = readInput()
  }
  send(value)
}\n`;
  const {graph,f} = await g(src);
  // outer not structured; literal false not applied; inner structured with literal true?
  console.log('\nlit false else-if true');
  console.log(graph.nodes.filter(n=>n.type==='statement').map(n=>`L${n.range.start.line} ${n.kind} r=${n.cfgReachable}`).join('\n'));
  console.log(graph.edges.filter(e=>e.type.startsWith('CFG_')).map(e=>{
    const f=graph.nodes.find(n=>n.id===e.from); const t=graph.nodes.find(n=>n.id===e.to);
    return `${e.type} L${f?.range?.start?.line||f?.type}->L${t?.range?.start?.line||t?.type}`;
  }).join('\n'));
  const t = await f.taint.invoke('cpg.taint', f.args, f.ctx);
  console.log('taint', t.payload.length);
}

EOF

