cd /private/tmp/baton-cpg-impl-review.YKCoUP/.baton/wt/grok-cpg-impl-review-45 && node --input-type=module <<'EOF'
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { AtlasCpgSlice, AtlasCpgTaint } from './impl/src/index.mjs';

// Confirm: pure braced if/else else-source works; else-if else-source fails
function setup(source) {
  const root = mkdtempSync(join(tmpdir(), 'adv4-'));
  const artifacts = mkdtempSync(join(tmpdir(), 'adv4a-'));
  mkdirSync(join(root, 'src'), { recursive: true });
  writeFileSync(join(root, 'src/a.js'), source);
  const taint = new AtlasCpgTaint({ artifactRoot: join(artifacts, 'taint'), maxGraphBytes: 512*1024, maxResultBytes: 512*1024, maxDepth: 24, maxPaths: 32, maxSourceBytes: 64*1024, maxReachDefPairs: 4096 });
  return { root, taint, ctx: { root, budgetTokens: 50000 }, args: { path: 'src/a.js', sourceNames:['readInput'], sinkNames:['send'], depth:20 } };
}

const pure = setup(`function readInput(){} function send(v){}
function run(a){
  let value = 0;
  if (a) {
    value = 1
  } else {
    value = readInput()
  }
  send(value)
}\n`);
console.log('pure else source', (await pure.taint.invoke('cpg.taint', pure.args, pure.ctx)).payload.length);

const elseif = setup(`function readInput(){} function send(v){}
function run(a,b){
  let value = 0;
  if (a) {
    value = 1
  } else if (b) {
    value = readInput()
  }
  send(value)
}\n`);
console.log('else-if mid source', (await elseif.taint.invoke('cpg.taint', elseif.args, elseif.ctx)).payload.length);

// re-anchor false positive: then source always reaches even with else-if that could kill
const fp = setup(`function readInput(){} function send(v){}
function run(a){
  let value = 0;
  if (a) {
    value = readInput()
  } else {
    value = 1
  }
  send(value)
}\n`);
// pure if/else may-reach is CORRECT to report path (may)
console.log('pure then source may', (await fp.taint.invoke('cpg.taint', fp.args, fp.ctx)).payload.length);

// Word count check later
EOF
wc -l impl/src/atlas-cpg.mjs
# print exact lines for citation
sed -n '109,156p' impl/src/atlas-cpg.mjs | cat -n
sed -n '161,181p' impl/src/atlas-cpg.mjs | cat -n

