function setup(source) {
  const root = mkdtempSync(join(tmpdir(), 'adv4-'));
  const artifacts = mkdtempSync(join(tmpdir(), 'adv4a-'));
  mkdirSync(join(root, 'src'), { recursive: true });
  writeFileSync(join(root, 'src/a.js'), source);
  const taint = new AtlasCpgTaint({ artifactRoot: join(artifacts, 'taint'), maxGraphBytes: 512*1024, maxResultBytes: 512*1024, maxDepth: 24, maxPaths: 32, maxSourceBytes: 64*1024, maxReachDefPairs: 4096 });
  return { root, taint, ctx: { root, budgetTokens: 50000 }, args: { path: 'src/a.js', sourceNames:['readInput'], sinkNames:['send'], depth:20 } };
}

const pure = setup(`function readInput(){} function send(v){}
function run(a){
  let value = 0;
  if (a) {
    value = 1
  } else {
    value = readInput()
  }
  send(value)
}\n`);
console.log('pure else source', (await pure.taint.invoke('cpg.taint', pure.args, pure.ctx)).payload.length);

const elseif = setup(`function readInput(){} function send(v){}
function run(a,b){
  let value = 0;
  if (a) {
    value = 1
  } else if (b) {
    value = readInput()
  }
