import { mkdtempSync, mkdirSync, writeFileSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { AtlasCpgSlice, AtlasCpgTaint, AtlasCpgDelta } from './impl/src/index.mjs';

const dir = () => mkdtempSync(join(tmpdir(), 'probe-'));
async function build(source) {
  const root = dir(); const artifacts = dir();
  mkdirSync(join(root, 'src'), { recursive: true });
  writeFileSync(join(root, 'src/a.js'), source);
  const cpg = new AtlasCpgSlice({ artifactRoot: join(artifacts,'cpg'), maxSourceBytes: 65536, maxArtifactBytes: 524288, maxReachDefPairs: 4096 });
  const ctx = { root, budgetTokens: 10000 };
  const path = (await cpg.invoke('cpg.build',{path:'src/a.js'},ctx)).refs[0].path;
  return { root, artifacts, cpg, ctx, graph: JSON.parse(readFileSync(path,'utf8')) };
}
function show(g, label) {
  const st = (line) => g.nodes.filter(n=>n.type==='statement'&&n.range.start.line===line).map(n=>({id:n.id.slice(-12),kind:n.kind,cfg:n.cfgReachable}));
  const cfg = g.edges.filter(e=>e.type.startsWith('CFG')).map(e=>({t:e.type,from:e.from.slice(-12),to:e.to.slice(-12)}));
  console.log('---', label, '---');
  console.log('stmts L2-8', st(2), st(3), st(4), st(5), st(6), st(7), st(8));
  console.log('cfg', JSON.stringify(cfg,null,0));
}

// else-if multiline
const src1 = \`function run(f,g) {
  if (f) {
    a()
  } else if (g) {
    b()
  } else {
    c()
  }
  done()
}\`;
const g1 = (await build(src1)).graph;
show(g1, 'else-if');

// dangling else
const src2 = \`function run(f) {
  if (f) {
    a()
  } else {
    if (f) {
      b()
    }
  }
  done()
}\`;
show((await build(src2)).graph, 'nested-else-if');

// sanitizer bypass via REACHING_DEF only
const src3 = \`function readInput(){} function sanitize(v){return v} function send(v){}
function run(){ let x=readInput(); let y=sanitize(x); let z=y; send(z) }\`;
const root=dir(); const art=dir(); mkdirSync(join(root,'src'),{recursive:true});
writeFileSync(join(root,'src/a.js'),src3);
const taint = new AtlasCpgTaint({artifactRoot:join(art,'t'),maxSourceBytes:65536,maxGraphBytes:524288,maxResultBytes:524288,maxDepth:24,maxPaths:32,maxReachDefPairs:4096});
const r = await taint.invoke('cpg.taint',{path:'src/a.js',sourceNames:['readInput'],sinkNames:['send'],sanitizerNames:['sanitize'],depth:20},{root,budgetTokens:10000});
console.log('sanitizer via copy chain', r.payload.length, r.payload[0]?.edgeTypes);

// literal !false not pruned
const src4 = \`function readInput(){} function send(v){} function run(){ if(!false){ send(readInput()) } }\`;
const t4 = await taint.invoke('cpg.taint',{path:'src/a.js',sourceNames:['readInput'],sinkNames:['send'],depth:20},{root,budgetTokens:10000});
console.log('!false literal', t4.payload.length);

// delta reachdef branch change
const before = \`function run(f){ let x=1; if(f){ x=2 } return x }\`;
const after = \`function run(f){ let x=1; if(f){ x=3 } return x }\`;
const br=dir(); const ar=dir(); const da=dir();
mkdirSync(join(br,'src'),{recursive:true}); mkdirSync(join(ar,'src'),{recursive:true});
writeFileSync(join(br,'src/a.js'),before); writeFileSync(join(ar,'src/a.js'),after);
const delta = new AtlasCpgDelta({artifactRoot:da,maxSourceBytes:65536,maxGraphBytes:524288,maxDeltaBytes:524288,maxImpactDepth:8,maxReachDefPairs:4096});
const dr = await delta.invoke('cpg.delta',{beforePath:'src/a.js',afterPath:'src/a.js',impactDepth:4},{beforeRoot:br,afterRoot:ar,budgetTokens:10000});
const artd = JSON.parse(readFileSync(dr.refs[0].path,'utf8'));
console.log('delta REACHING_DEF changes', artd.edgeChanges.filter(e=>e.type==='REACHING_DEF').length);
console.log('delta def_use impact', artd.impact.filter(i=>i.reason==='def_use').length);
