import { parse, Lang } from '@ast-grep/napi';
const src = \`function run(f,g) {
  if (f) {
    a()
  } else if (g) {
    b()
  } else {
    c()
  }
  done()
}\`;
const root = parse(Lang.JavaScript, src).root();
function walk(node, depth=0) {
  const k = node.kind();
  if (k === 'if_statement' || k === 'statement_block' || k === 'else_clause') {
    console.log('  '.repeat(depth)+k, node.text().slice(0,60).replace(/\\n/g,'\\\\n'));
    if (k==='if_statement') {
      try {
        const c=node.field('consequence'); const a=node.field('alternative'); const cond=node.field('condition');
        console.log('  '.repeat(depth)+'  cons:', c?.kind(), 'alt:', a?.kind(), a?.children().map(ch=>ch.kind()));
      } catch(e){}
    }
  }
  for (const ch of node.children()) if (ch.isNamed()) walk(ch, depth+1);
}
walk(root);

