import { mkdtempSync, mkdirSync, writeFileSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os'; import { join } from 'node:path';
import { AtlasCpgDelta } from './impl/src/index.mjs';
const br=mkdtempSync(join(tmpdir(),'b-')); const ar=mkdtempSync(join(tmpdir(),'a-')); const da=mkdtempSync(join(tmpdir(),'d-'));
mkdirSync(join(br,'src'),{recursive:true}); mkdirSync(join(ar,'src'),{recursive:true});
const before = \`function run(f){ let x=readInput(); if(f){ x=safe() } send(x) }\`;
const after = \`function run(f){ let x=readInput(); if(f){ x=safe(); x=readInput() } send(x) }\`;
writeFileSync(join(br,'src/a.js'),before); writeFileSync(join(ar,'src/a.js'),after);
const delta = new AtlasCpgDelta({artifactRoot:da,maxSourceBytes:65536,maxGraphBytes:524288,maxDeltaBytes:524288,maxImpactDepth:8,maxReachDefPairs:4096});
const dr = await delta.invoke('cpg.delta',{beforePath:'src/a.js',afterPath:'src/a.js',impactDepth:4},{beforeRoot:br,afterRoot:ar,budgetTokens:10000});
const art = JSON.parse(readFileSync(dr.refs[0].path,'utf8'));
console.log('node mods', art.nodeChanges.filter(n=>n.change==='modified').length);
console.log('edge adds', art.edgeChanges.filter(e=>e.change==='added').map(e=>e.type));
console.log('edge removes', art.edgeChanges.filter(e=>e.change==='removed').map(e=>e.type));
console.log('reachdef changes', art.edgeChanges.filter(e=>e.type==='REACHING_DEF'));
"

